    final groups = <String>[];
    final stack = Stack<int>();

    for (var i = 0; i < input.length; i++) {
      if (input[i] == '(') {
        stack.push(i);
      } else if (input[i] == ')') {
        if (!stack.isEmpty) {
          int start = stack.pop();
          String group = input.substring(start, i + 1);
          groups.add(group);
        }
      }
    }

    return groups;
  }
}

