import 'dart:math';

/// Calculates the Mean Absolute Deviation (MAD) of a list of [double] values.
///
/// MAD measures the average distance between each data point and the mean of the dataset.
/// It provides a measure of how spread out the data points are from the center.
///
/// Example:
/// ```dart
/// final deviations = [1.0, 2.5, 3.0];
/// print(meanAbsoluteDeviation(deviations)); // Output: 1.166...
/// ```
double meanAbsoluteDeviation(List<double> numbers) {
  if (numbers.isEmpty) {
    throw ArgumentError('Cannot compute deviation for an empty list');
  }

  final sum = numbers.fold(0.0, (sum, num) => sum + num);
  final mean = sum / numbers.length;

  final absoluteDeviations = numbers.map((num) => abs(num - mean));
  final totalDeviation = absoluteDeviations.fold(0.0, (total, dev) => total + dev);

  return totalDeviation / numbers.length;
}
