// 3. Taking the average of these differences.

/// Calculates the mean absolute deviation of a given list of [numbers].
///
/// This measures how much the numbers vary from their average value.
/// It's calculated as the average of the absolute differences between each number
/// and the mean of all numbers.
///
/// Example usage:
/// ```dart
/// final data = [5.0, 7.0, 9.0];
/// print(meanAbsoluteDeviation(data)); // Output: 1.33...
/// ```
///
/// Returns the mean absolute deviation or `0.0` for an empty list.
double meanAbsoluteDeviation(List<double> numbers) {
  if (numbers.isEmpty) return 0.0;

  // Step 1: Find the mean of all numbers
  var sum = numbers.fold(0.0, (prev, num) => prev + num);
  var mean = sum / numbers.length;

  // Step 2: Compute absolute differences from the mean
  var totalDeviation = numbers.map((num) => abs(num - mean)).reduce((a, b) => a + b);

  // Step 3: Average those differences to get MAD
  return totalDeviation / numbers.length;
}
