// This function returns the largest proper divisor of a number [n].
// A proper divisor is any positive integer that divides [n] without leaving a remainder.
//
// The algorithm works by iterating from 2 up to the square root of [n], checking both
// [i] and its complement ([n / i]) as potential divisors. If either is larger than the current maximum,
// it updates the maximum.
//
// Time complexity is O(√n), which is efficient for large values of [n].

int largestDivisor(int n) {
  int max = -1;

  for (var i = 2; i <= sqrt(n); i++) {
    if (n % i == 0 && i > max) {
      max = i;
    }

    final j = n ~/ i;
    if (j != i && j > max) {
      max = j;
    }
  }

  return max;
}
