bool _isFibonacci(int number) {
  double phi = (1 + sqrt(5)) / 2;
  double fibApproximation = pow(phi, number) / sqrt(5);
  bool isCloseEnough = abs(fibApproximation.round() - fibApproximation) < 1e-6;
  return isCloseEnough || _isPerfectSquare((number * number) + 4);
}

// A number x is a Fibonacci number iff either its square plus four or minus four is a perfect square.
bool _isPerfectSquare(double x) {
  final s = sqrt(x);
  return s.isFinite && s.toInt().toDouble() == s;
