bool correctBracketing(String brackets) {
  // If the input string is empty, it's trivially balanced.
  if (brackets.isEmpty) return true;

  // Use a stack to keep track of opening brackets.
  List<String> stack = [];

  // Iterate over each character in the input string.
  for (int i = 0; i < brackets.length; i++) {
    String currentChar = brackets[i];

    // Push opening brackets onto the stack.
    if (currentChar == '(' || currentChar == '[' || currentChar == '{') {
      stack.add(currentChar);
    } 
    // Check and pop matching closing brackets from the stack.
    else if (currentChar == ')') {
      if (stack.isNotEmpty && stack.last == '(') {
        stack.removeLast(); // Match found, remove the corresponding opening bracket
      } else {
        return false; // Mismatched or unbalanced bracket
