/// // Output: true
/// ```
///
/// If the input contains other characters or invalid sequences like "))((", this will also return false.
bool correctBracketing(String brackets) {
  int openCount = 0;

  for (int i = 0; i < brackets.length; i++) {
    final char = brackets[i];

    if (char == '(') {
      openCount++;
    } else if (char == ')') {
      openCount--;

      if (openCount < 0) {
