// Check if a string of brackets is correctly balanced.
// A bracket sequence is valid if:
// - Every opening bracket has a closing one in the same order.
// - Braces are properly nested and closed in reverse order.

// This function returns `true` if all open brackets have corresponding close brackets
// and they're properly nested. It uses a simple counter to track the balance of brackets.
// If at any point there's more closing than opening brackets, it immediately returns `false`.
// At the end, ensures that the total number of open and close brackets match exactly.

bool correctBracketing(String brackets) {
  if (brackets.isEmpty) return true;

  // Start with zero balance between open and close brackets
  int balance = 0;

  for (int i = 0; i < brackets.length; i++) {
    final char = brackets[i];

    if (char == '(') {
      // Increase balance when encountering an open parenthesis
      balance++;
    } else if (char == ')') {
      // Decrease balance when encountering a close parenthesis
      balance--;

      // If balance goes negative, we've encountered too many closing brackets early on
      if (balance < 0) return false;
    }
  }

  // After processing all characters, check if all brackets were matched
  return balance == 0;
}
