      // Standard case with both neighbors available
      result[i] = (xs[i + 1] - xs[i - 1]) / (2 * dx);
    } else if (dx > 1e-8) {
      // Only right neighbor is available (last element)
      // Use forward difference approximation
      result[i] = (xs[i + 1] - xs[i]) / dx;
    } else {
