import 'dart:math';

String circularShift(int x, int shift) {
  if (x == 0) return "0";

  final digits = [];
  var num = x;
  while (num != 0) {
    digits.add(num % 10);
    num ~/= 10;
  }

  // Handle negative numbers by converting to positive and tracking sign
  bool isNegative = false;
  if (x < 0) {
    isNegative = true;
    num = -x;
  } else {
    num = x;
  }

  // Count the number of digits in the original number
  int digitCount = digits.length;

  // Normalize the shift value modulo digit count
  int effectiveShift = shift % digitCount;
  if (effectiveShift < 0) {
    effectiveShift += digitCount;
  }

  // Calculate new position for each digit after shifting
  List<int> shiftedDigits = List.filled(digitCount, 0);
  for (int i = 0; i < digitCount; i++) {
    int newIndex = (i + effectiveShift) % digitCount;
    shiftedDigits[newIndex] = digits[i];
  }

  // Convert shifted digits back to integer
  int resultNum = 0;
  for (var d in shiftedDigits.reversed) {
    resultNum = resultNum * 10 + d;
  }

  if (isNegative) {
    resultNum *= -1;
  }

  return resultNum.toString();
}
