class AES_CBC_Mode {
  final List<int> _key;
  final List<int> _iv;

  AES_CBC_Mode(this._key, this._iv);

  String encrypt(String plaintext) {
    final inputBytes = utf8.encode(plaintext);
    final output = <int>[];

    for (var i = 0; i < inputBytes.length; i += 16) {
      final block = inputBytes.sublist(i, i + 16).toList();

      if (block.length < 16) {
        // Pad the block to be exactly 16 bytes long
        var paddingLength = 16 - block.length;
        for (var j = 0; j < paddingLength; j++) {
          block.add(paddingLength);
        }
      }

      // XOR with IV or previous ciphertext block
      for (var k = 0; k < block.length; k++) {
        block[k] ^= _iv[k];
