      case 'e':
      case 'i':
      case 'o':
      case 'u':
        hasVowelAndExclamation ||= true;
        break;
      default:
        containsNonVowel = true;
        break;
    }
  }

  if (hasVowelAndExclamation && !containsNonVowel) {
    return false; // Not boring because it's only vowels and exclamation
