  if (dict == null || dict.isEmpty) return true;

  final keys = MapIterable<String>.fromEntries(dict.entries).keys;
  bool allUpper = true;
  bool allLower = true;

  for (final key in keys) {
    String sKey = key.toString();
    if (!sKey.startsWith('[')) {
      // Check for snake_case or camelCase patterns.
      var hasUnderscore = sKey.contains('_');
      var firstCharIsUppercase = sKey[0].isUpperCase;
      var isAllCamelCase = !hasUnderscore && (firstCharIsUppercase || sKey.length > 1);

