      // Adjust rounding direction based on whether we're at the midpoint or beyond
      if (differenceFromMidpoint > 0) {
        roundedNumber += 1;
      } else if (differenceFromMidpoint < 0) {
        roundedNumber -= 1;
      }
    }

    return roundedNumber;
  } catch (_) {
    return 0;
  }
