bool moveOneBall(List<int> arr) {
  int left = 0;
  int right = arr.length - 1;

  while (left < right) {
    if (arr[left] == arr[right]) {
      return true;
    } else if (arr[left] != arr[right]) {
      // Swap the elements to make them equal.
      int temp = arr[left];
      arr[left] = arr[right];
      arr[right] = temp;
      left++;
      right--;
    }
  }

  // If we reach here, all balls are in pairs or one ball remains unpaired.
  // So check if there's exactly one ball remaining and it is not part of a pair.
  bool hasUnmatched = false;
  for (int i = 0; i < arr.length; i++) {
    if (i + 1 < arr.length && arr[i] == arr[i + 1]) {
      i++; // Skip the next element since they form a pair.
    } else {
      hasUnmatched = true;
      break;
    }
  }

  return !hasUnmatched;
}
