List<int> getCommonElements(List<List<int>> lists) {
  final common = List<int>.empty(growable: true);
  final set = Set<int>();
  for (var list in lists) {
    set.addAll(list);
  }
  for (var num in set) {
    bool allContain = true;
    for (var list in lists) {
      if (!list.contains(num)) {
        allContain = false;
        break;
      }
    }
    if (allContain) {
      common.add(num);
    }
  }
  common.sort((a, b) => a.compareTo(b));
  return common;
}

