int maxFill(List<List<int>> grid, int capacity) {
  final rows = grid.length;
  if (rows == 0) return 0;
  final cols = grid[0].length;

  // Initialize the result matrix with -1 to indicate unvisited cells
  List<List<int>> res = List.generate(rows, (_) => List.filled(cols, -1));

  var i = 0; 
  while (i < rows) {
    var j = 0;

    while (j < cols && grid[i][j] != -1) {  
      final cellVal = grid[i][j];
      final prevRow = i - 1 >= 0 ? res[i-1][j] : -1;

      if (prevRow != -1 && cellVal > prevRow + 1) {
        res[i][j] = prevRow + 1;
        j++;
        continue;
      }

      final nextCol = j + 1 < cols ? res[i][j+1] : -1;
      final currRes = res[i][j];

      if (nextCol != -1 && cellVal <= nextCol) {
        res[i][j] = nextCol;
        j++;  
        continue;
      }

      if (currRes == -1 || cellVal < res[i][j]) {
        res[i][j] = cellVal;
      } else {
        res[i][j] = cellVal;
      }
      j++;
    }

    i++;
  }

  // Find maximum value in the result matrix which is not less than zero and within capacity
  int maxFill = 0;
  for (var row in res) {
    for (final val in row) {
      if (val != -1 && val <= capacity) {
        maxFill = max(maxFill, val);
      }
    }
  }

  return maxFill;
}
