int maxFill(List<List<int>> grid, int capacity) {
  final rows = grid.length;
  if (rows == 0) return 0;

  final cols = grid[0].length;
  if (cols == 0) return 0;

  // Directions for up, down, left, right
  const directions = <List<int>>[
    [-1, 0],
    [1, 0],
    [0, -1],
    [0, 1]
  ];

  final visited = List.generate(rows, (_) => List.filled(cols, false));

  var totalFilled = 0;

  void dfs(int row, int col, int currentCapacity) {
    if (row < 0 || row >= rows || col < 0 || col >= cols || visited[row][col] || currentCapacity <= 0) return;

    // If the cell is filled with water and we can't go further in this direction, stop here.
    if (grid[row][col] > 0 && currentCapacity == 0) return;

    // Mark as visited to prevent revisiting
    visited[row][col] = true;

    // Check all four directions
    for (final dir in directions) {
      final newRow = row + dir[0];
      final newCol = col + dir[1];

      // Calculate how much capacity would be needed to fill this next step
      final requiredCapacity = (grid[newRow][newCol] == 0 ? 0 : grid[newRow][newCol]);

      if (requiredCapacity > 0) {
        // We need at least that amount of capacity to proceed
        if (currentCapacity >= requiredCapacity) {
          dfs(newRow, newCol, currentCapacity - requiredCapacity);
        }
      } else {
        // No requirement, just continue moving without using any more capacity
        dfs(newRow, newCol, currentCapacity);
      }

      // After backtracking from a direction, restore the visited state
      visited[row][col] = false;
    }

    // Add the current cell's value to total filled (if it's not part of an empty space)
    if (grid[row][col] != 0) {
      totalFilled += grid[row][col];
    }
  }

  // Start DFS from each cell in the grid
  for (var r = 0; r < rows; r++) {
    for (var c = 0; c < cols; c++) {
      if (!visited[r][c]) {
        dfs(r, c, capacity); 
      }
    }
  }

  return totalFilled;
}
