int maxFill(List<List<int>> grid, int capacity) {
  final rows = grid.length;
  if (rows == 0) return 0;

  final cols = grid[0].length;
  if (cols == 0) return 0;

  // Initialize the maximum filled value to zero.
  var maxFilled = 0;

  for (var rowStart in 0...rows - 1) {
    for (var colStart in 0...cols - 1) {
      // For each starting point, find the largest possible square that can be filled with available space.
      var currentRow = rowStart;
      var currentCol = colStart;
      var size = 0;

      while (
        currentRow < rows && 
        currentCol < cols &&
        grid[currentRow][currentCol] >= 0
      ) {
        // Check if we can fill this cell and expand as much as possible.
        // To determine how far we can go, check all four directions or track expansion.

        // Since it's a square, increment both dimensions at once until hitting boundary or invalid cells.
        size++;
        currentRow++;
        currentCol++;

        // If any of these are out of bounds or not valid, stop expanding.
        if (currentRow >= rows || currentCol >= cols || grid[currentRow][currentCol] < 0) break;
      }

      // After finding the maximum possible square from (rowStart, colStart), update the maxFilled accordingly.
      maxFilled = max(maxFilled, size * size);

      // Also consider whether using less than full square might give better results due to capacity constraints. But since we're maximizing the filled area, just taking the size is sufficient here.
    }
  }

  return min(maxFilled, capacity);
