String getClosestVowel(String word) {
  final vowels = {'a', 'e', 'i', 'o', 'u'};

  if (word.isEmpty) return '';

  int closestIndex = -1;
  double minDistance = Double.maxFinite;

  for (int i = 0; i < word.length; i++) {
    final char = word[i].toLowerCase();

    if (vowels.contains(char)) {
      // Calculate distance from the current position to the start and end of the string
      final leftDistance = i.toDouble(); // Distance to the beginning
