List<int> minPath(List<List<int>> grid, int k) {
  final rows = grid.length;
  final cols = grid[0].length;

  // Initialize DP table with infinity values
  final dp = List.generate(rows * cols + 1, (_) => List<double>.filled(cols * rows + 1, double.infinity));

