  // Check for empty or too short filename
  if (fileName.isEmpty || fileName.length < 4) {
    return "Invalid file name";
  }

  // Split on last dot to get extension
  final parts = fileName.split('.');
  final extIndex = parts.lastIndexOf('.');
  if (extIndex == -1 || extIndex == 0) {
    return "Invalid file name";
  }

  final extension = parts[parts.length - 1];

  // Validate extension
  for (final c in extension.split('')) {
    if (!c.isLetter && !c.isDigit && c != '_') {
      return "Invalid file name";
    }
  }

  return "Valid file name";
}
