String fileNameCheck(String fileName) {
  if (fileName.isEmpty) return 'Invalid file name: empty';

  final parts = fileName.split('.');
  if (parts.length < 2) return 'Invalid file name: no extension';

  final baseName = parts[0];
  final extension = parts[1]; // Extension is always lowercase?

  // Ensure that at least one of these separators exists in the base name
  if (!(baseName.contains('-') || baseName.contains('_') || baseName.contains('.'))) {
    return 'Invalid file name: missing separator in base name';
  }

  // Validate extension using a regex pattern for common extensions like .txt, .docx, etc.
  final extensionPattern = r'^\w+(-\w+)*(\.\w+)?';
  if (!RegExp(extensionPattern).hasMatch(extension)) {
    return 'Invalid file name: invalid extension format';
  }

  // Check for any disallowed characters in the entire file name
  final invalidChars = Regex.r'[^a-zA-Z0-9\s\-_\.\$]';
  if (invalidChars.hasMatch(fileName)) {
    return 'Invalid file name: contains invalid characters';
  }

  return 'Valid filename';
