String wordsInSentence(String sentence) {
  final List<String> words = [];
  int index = 0;

  while (index < sentence.length) {
    if (sentence[index] == ' ') {
      // Skip spaces between words
      index++;
      continue;
    }

    int wordStartIndex = index;
    while (index < sentence.length && !isSpace(sentence[index])) {
      index++;
    }
    String word = sentence.substring(wordStartIndex, index);
    words.add(word);
  }

  return words.join(' ');
}

