bool rightAngleTriangle(num a, num b, num c) {
  // Check if all inputs are non-negative numbers.
  if (a < 0 || b < 0 || c < 0) return false;

  // Convert to double for calculations.
  final aDouble = a.toDouble();
  final bDouble = b.toDouble();
  final cDouble = c.toDouble();

  // Calculate the squares of the sides using pow function.
  final aSquared = pow(aDouble, 2);
  final bSquared = pow(bDouble, 2);
  final cSquared = pow(cDouble, 2);

  // Sort the sides in ascending order.
  var sortedSides = [aSquared, bSquared, cSquared];
  sortedSides.sort(); 

  // Verify Pythagorean theorem with floating point precision consideration.
  const tolerance = 1e-6; 
  bool isRightTriangle = abs(sortedSides[0] + sortedSides[1] - sortedSides[2]) < tolerance;

  return isRightTriangle;
}
